USE [db_infrahub];
GO
IF COL_LENGTH('tbl_m_zones', 'latitude') IS NULL
BEGIN
    ALTER TABLE tbl_m_zones ADD latitude DECIMAL(11,8) NULL, longitude DECIMAL(11,8) NULL;
END
GO
IF OBJECT_ID('dbo.tbl_t_dashboard_acknowledges', 'U') IS NULL
BEGIN
    CREATE TABLE dbo.tbl_t_dashboard_acknowledges (
        id BIGINT IDENTITY(1,1) PRIMARY KEY,
        anomaly_key NVARCHAR(150) NOT NULL,
        panel NVARCHAR(30) NULL,
        zone_id UNIQUEIDENTIFIER NULL,
        metric_name NVARCHAR(50) NULL,
        acknowledged_value NVARCHAR(50) NULL,
        is_active BIT NOT NULL DEFAULT 1,
        acknowledged_by UNIQUEIDENTIFIER NULL,
        acknowledged_at DATETIME NOT NULL DEFAULT GETDATE(),
        released_at DATETIME NULL,
        created_at DATETIME NOT NULL DEFAULT GETDATE(),
        updated_at DATETIME NOT NULL DEFAULT GETDATE()
    );
END
GO
